package com.example

import com.example.ExamQuestionHelper.QSpec

object HealthLiveExamAthleticsBank2 {
    private const val T = "මලල ක්‍රීඩා ඉසව්, ශිල්පීය ක්‍රම හා නීති රීති"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("මලල ක්‍රීඩාවේ 'ඇවිදීමේ තරග' (Race Walking) ඉසව්වලදී ක්‍රීඩකයා අනිවාර්යයෙන් පිළිපැදිය යුතු පළමු මූලික නීතිය කුමක්ද?", "නිරන්තරයෙන්ම එක් පාදයක් පොළොව සමග ස්පර්ශව පැවතීම (Continuous Contact)", "හැකි උපරිම වේගයෙන් දිවීම", "දෑත් ඉහළට ඔසවාගෙන ඇවිදීම", "දෙපා එකවර බිම තැබීම", "පසුපස පාදය බිමෙන් එසවීමට පෙර ඉදිරි පාදයේ විලුඹ බිම ස්පර්ශ විය යුතුය; දෙපාම එකවර බිමෙන් එසවීම (Loss of contact) වරදකි."),
        q("ඇවිදීමේ තරගයකදී ඉදිරියට තබන පාදය සම්බන්ධයෙන් පවතින අනිවාර්ය නීතිය කුමක්ද?", "පාදය බිම ස්පර්ශ වන මොහොතේ සිට සිරුර සිරස් වන තෙක් දණහිස නොනැමී කෙළින් පැවතීම", "දණහිස නිරන්තරයෙන් නවා තබා ගැනීම", "පාදය පසෙකට විසි කිරීම", "ඇඟිලි තුඩුවලින් ඇවිදීම", "දණහිස නැමීම (Bent knee) බරපතළ වරදක් වන අතර විනිසුරුවන් ඒ සඳහා අනතුරු ඇඟවීම් නිකුත් කරයි."),
        q("ඇවිදීමේ තරගයකදී විනිසුරුවන් විසින් ක්‍රීඩකයෙකුට නීති කඩකිරීමක් පිළිබඳ අනතුරු අඟවන සංකේත පුවරුවේ (Paddle) දැක්වෙන සංකේත මොනවාද?", "බිම ස්පර්ශය නොමැතිවීමට රැළි රේඛාවක් (~) සහ දණහිස නැමීමට අංශක හැඩැති කෝණයක් (>)", "කහ සහ රතු කාඩ්පත් පමණි", "අංක 1 සහ 2", "හරස් ඉරක්", "විනිසුරුවන් කහ පැහැති පැඩලය පෙන්වා ක්‍රීඩකයාට තම වරද නිවැරදි කරගැනීමට අවස්ථාව ලබාදෙයි."),
        q("ඇවිදීමේ තරගයකදී විවිධ විනිසුරුවන් තිදෙනෙකුගෙන් රතු කාඩ්පත් (Red Cards) 3ක් ලැබුණු ක්‍රීඩකයෙකුට සිදුවන්නේ කුමක්ද?", "තරගයෙන් නුසුදුස්සෙකු (DQ) වී ඉවත් වීමට සිදුවීම", "තත්පර 10ක ප්‍රමාදයක් පමණි", "ලකුණු අඩු වීම", "කිසිදු දඬුවමක් නොලැබීම", "ප්‍රධාන විනිසුරු විසින් රතු පැහැති පුවරුව පෙන්වා ක්‍රීඩකයා තරගයෙන් ඉවත් කරනු ලබයි."),
        q("මිටිය විසිකිරීමේ (Hammer Throw) ඉසව්වේ මිටියේ ප්‍රධාන කොටස් 3 නිවැරදිව දැක්වෙන පිළිතුර කුමක්ද?", "ලෝහමය බෝලය (Head), වානේ කම්බිය (Wire) සහ ග්‍රහණ අඬුව (Grip)", "ලී මිට, යකඩ තලය සහ දම්වැල", "බෝලය, රබර් පටිය සහ කොක්ක", "යකඩ දණ්ඩ, තැටිය සහ කඹය", "මිටිය යනු වානේ කම්බියකින් ග්‍රහණ අඬුවට සම්බන්ධ කරන ලද ඝන ලෝහමය බෝලයකි."),
        q("ජ්‍යෙෂ්ඨ පිරිමි මිටිය විසිකිරීමේ ඉසව්වේ මිටියේ සම්මත නිල බර ප්‍රමාණය කොපමණද?", "කිලෝග්‍රෑම් 7.26කි (රාත්තල් 16)", "කිලෝග්‍රෑම් 5.00කි", "කිලෝග්‍රෑම් 4.00කි", "කිලෝග්‍රෑම් 6.00කි", "පිරිමි මිටියේ බර යගුලියේ බරට සමාන වන අතර එය කිලෝග්‍රෑම් 7.26ක් (7.260 kg) වේ."),
        q("ජ්‍යෙෂ්ඨ කාන්තා මිටිය විසිකිරීමේ ඉසව්වේ මිටියේ සම්මත නිල බර ප්‍රමාණය කීයද?", "කිලෝග්‍රෑම් 4.00කි", "කිලෝග්‍රෑම් 3.00කි", "කිලෝග්‍රෑම් 5.00කි", "කිලෝග්‍රෑම් 2.00කි", "කාන්තා මිටියේ බර කිලෝග්‍රෑම් 4.00ක් (කාන්තා යගුලියට සමාන) වේ."),
        q("මිටිය විසිකිරීමේදී ක්‍රීඩකයන් තම දෑත් ආරක්ෂා කර ගැනීමට සහ ග්‍රහණය තහවුරු කර ගැනීමට භාවිත කරන්නේ මොනවාද?", "ඇඟිලි තුඩු විවෘත වූ විශේෂිත සම් අත්වැසුම් (Gloves)", "රබර් අත්වැසුම්", "ලොම් අත්වැසුම්", "අත් ආවරණ කිසිවක් භාවිත කළ නොහැක", "අත්ල තුවාල වීම වැළැක්වීමට සහ සුමට මුදාහැරීමකට විශේෂිත විසිකිරීමේ අත්වැසුම් භාවිතයට නීතියෙන් අවසර ඇත."),
        q("රිටි පැනීමේ (Pole Vault) ඉසව්වේදී රිට ගසා ඉහළට එසවීම සඳහා බිම සවිකර ඇති ලෝහමය පෙට්ටිය කුමක්ද?", "රිටි පෙට්ටිය (Planting Box)", "නවත්වන පුවරුව", "පිටත්වීමේ ලෑල්ල", "ආරම්භක කුට්ටිය", "ධාවන පථය කෙළවර පිහිටි බෑවුම් සහිත ලෝහ පෙට්ටිය තුළට රිටි තුඩ රුවා ඉහළට එසවේ."),
        q("රිටි පැනීමේදී ක්‍රීඩකයා භාවිත කරන රිට (Pole) සාදා තිබිය යුතු සම්මත ද්‍රව්‍යය කුමක්ද?", "ෆයිබර්ග්ලාස් හෝ කාබන් ෆයිබර් වැනි ඕනෑම නම්‍යශීලී ද්‍රව්‍යයක්", "වානේ බටයක් පමණි", "ඝන දැව ලීයක්", "ඇලුමිනියම් බටයක්", "රිට සඳහා දිග හෝ බර පිළිබඳ සීමාවක් නොමැති අතර නම්‍යශීලී ෆයිබර්ග්ලාස් රිටි බහුලව භාවිත වේ."),
        q("රිටි පැනීමේදී පිම්ම නිෂ්ප්‍රභ වන (Foul) අවස්ථාවක් නොවන්නේ කුමක්ද?", "තීරුවට කිසිදු හානියක් නොවී ක්‍රීඩකයා සාර්ථකව තීරුව පසුකර මෙට්ටයට වැටීම", "ක්‍රීඩකයාගේ පහරින් හරස් තීරුව ආධාරකයෙන් බිම වැටීම", "රිට මුදාහැරීමෙන් පසු එය හරස් තීරුවේ වැදී තීරුව බිම වැටීම", "ක්‍රීඩකයා පනින අතරතුර අතින් තීරුව අල්ලා බිම වැටීම වැළැක්වීම", "තීරුව නොවැටී මෙට්ටය මතට ගොඩබැසීම සාර්ථක වලංගු පිම්මකි."),
        q("මලල ක්‍රීඩා පිටියේ පැනීමේ සහ විසිකිරීමේ ඉසව් (Field Events) පාලනය කරන ප්‍රධාන විනිසුරුවරයා කවුද?", "පිටිය තීරක හෙවත් ෆීල්ඩ් රෙෆ්රි (Field Referee)", "ධාවන තීරක (Track Referee)", "ආරම්භක විනිසුරු", "කාල ගණක විනිසුරු", "පිටිය තීරක විසින් උස, දුර පැනීම් සහ සියලු විසිකිරීමේ ඉසව්වල නීති හා ගැටලු විසඳනු ලබයි."),
        q("මලල ක්‍රීඩා තරගයකට පෙර ක්‍රීඩකයන්ගේ නිල ඇඳුම්, අංක තහඩු සහ ස්පයික් සපත්තු පරීක්ෂා කරන විශේෂිත කාමරය කුමක්ද?", "කැඳවුම් කුටිය (Call Room)", "වෛද්‍ය කාමරය", "විවේකාගාරය", "විනිසුරු කුටිය", "Call room තුළදී සියලුම ක්‍රීඩකයන් නිල නීතිරීතිවලට අනුකූලදැයි දැඩි ලෙස පරීක්ෂා කර ධාවන පථයට යොමු කරයි."),
        q("මලල ක්‍රීඩා තරගයකදී ක්‍රීඩකයන් තම ජර්සියෙහි පැළඳිය යුතු අංක තහඩු (Bibs) ගණන සාමාන්‍යයෙන් කීයද?", "පපුවේ සහ පිටුපස පැළඳීමට අංක තහඩු 2ක්", "පපුවේ පමණක් 1ක්", "අංක තහඩු 4ක්", "අංක තහඩු අවශ්‍ය නොවේ", "උස පැනීම සහ රිටි පැනීම හැර අනෙක් සියලු ඉසව් සඳහා ඉදිරිපස හා පසුපස අංක තහඩු 2ක් අනිවාර්ය වේ."),
        q("උස පැනීමේ සහ රිටි පැනීමේ ඉසව්වල නිරත වන ක්‍රීඩකයන්ට එක් අංක තහඩුවක් පමණක් පැළඳීමට අවසර දී ඇත්තේ ඇයි?", "පිටුපස ඇති අංක තහඩුව තීරුවේ ගැටී තීරුව බිම වැටීම වැළැක්වීම සඳහා", "ඔවුන්ට වියදම අඩු කිරීමට", "එය ලස්සන නිසා", "ඔවුන් වේගයෙන් නොදුවන නිසා", "පිටුපසින් තීරුව පසුකරන බැවින් අංක තහඩුව තීරුවේ නොගැටෙන සේ පපුවේ හෝ පිටුපස එකක් පමණක් පැළඳීමට අවසර ලැබේ."),
        q("ෆොස්බරි ෆ්ලොප් ක්‍රමයේදී ක්‍රීඩකයාගේ ශරීරයේ ගුරුත්ව කේන්ද්‍රය (Center of Gravity) පිහිටන්නේ කොහේද?", "හරස් තීරුවට පහළින් (තීරුවට යටින්)", "තීරුවට වඩා අඩි 2ක් ඉහළින්", "ක්‍රීඩකයාගේ හිස මත", "මෙට්ටය මත", "ෆ්ලොප් ක්‍රමයේ විශිෂ්ටතම ජෛව යාන්ත්‍රික වාසිය වන්නේ සිරුර දුන්නක් මෙන් නමන විට ගුරුත්ව කේන්ද්‍රය තීරුවට යටින් ගමන් කිරීමයි."),
        q("යගුලිය දැමීමේදී උපරිම දුරක් ලබාගැනීම සඳහා න්‍යායාත්මක ප්‍රශස්ත මුදාහැරීමේ කෝණය (Angle of Release) අංශක කීයද?", "අංශක 36 සිට 40 දක්වා", "අංශක 90ක්", "අංශක 10ක්", "අංශක 60ක්", "උරහිස් මට්ටමේ උසක සිට බිමට වැටෙන බැවින් 45ට වඩා මඳක් අඩු අංශක 37ක් පමණ ප්‍රශස්ත කෝණය වේ."),
        q("හෙල්ල විසිකිරීමේදී හෙල්ලය වාතයේ පාවී යාමට උපකාරී වන ප්‍රශස්ත මුදාහැරීමේ කෝණය කොපමණද?", "අංශක 32 සිට 36 දක්වා", "අංශක 50 සිට 60 දක්වා", "අංශක 15 සිට 20 දක්වා", "අංශක 70ක්", "වායුගතික ප්ලාව්‍යතාව (Aerodynamic lift) උපරිම කර ගැනීමට හෙල්ලය අංශක 33-35 අතර කෝණයකින් මුදාහරියි."),
        q("විසිකිරීමේ ඉසව්වලදී පාදවලින් ආරම්භ වී උකුල, කඳ, උරහිස සහ අත හරහා අවිය වෙත බලය සම්ප්‍රේෂණය වීමේ යාන්ත්‍රණය කුමක්ද?", "චාලක දාමය (Kinetic Chain)", "ගුරුත්ව දාමය", "ලිස්සන දාමය", "නම්‍යශීලී දාමය", "ශරීරයේ විශාල මාංශපේශීවලින් උපදින බලය කුඩා පේශි වෙත අනුක්‍රමිකව එකතු වී උපරිම වේගයක් අවියට ලබා දෙයි."),
        q("මලල ක්‍රීඩා තරගයක නිල තීරණයකට එරෙහිව විරෝධතාවක් (Protest) ඉදිරිපත් කළ යුතු නියමිත කාලසීමාව කුමක්ද?", "නිල ප්‍රතිඵලය ප්‍රකාශයට පත්කර මිනිත්තු 30ක් ඇතුළත", "පැය 24ක් ඇතුළත", "දින 3කට පසු", "තරගය අතරතුරදීම පමණි", "ප්‍රතිඵලය පුවරුවේ ප්‍රදර්ශනය කර මිනිත්තු 30ක් ඇතුළත ලිඛිතව අදාළ තීරකවරයා වෙත විරෝධතාව ඉදිරිපත් කළ යුතුය."),
        q("තීරකවරයාගේ (Referee) තීරණයටද එකඟ නොවන්නේ නම් අවසාන තීන්දුව සඳහා අභියාචනය කළ යුත්තේ කුමන ආයතනයටද?", "අභියාචනා ජූරි සභාවට (Jury of Appeal)", "පොලිසියට", "ක්‍රීඩා අමාත්‍යවරයාට", "පාසල් විදුහල්පතිට", "නියමිත තැන්පතු මුදලක් ගෙවා ජූරි සභාව වෙත ඉදිරිපත් කරන අභියාචනයේ තීරණය අවසාන සහ අනුලංඝනීය වේ."),
        q("දකුණු ආසියානු මලල ක්‍රීඩා ඉතිහාසයේ මීටර් 100 ඉසව්ව තත්පර 10ට අඩුවෙන් (තත්පර 9.96) නිමකළ ප්‍රථම සහ එකම ශ්‍රී ලාංකික ක්‍රීඩකයා කවුද?", "යුපුන් අබේකෝන්", "සුගත් තිලකරත්න", "චින්තක ද සොයිසා", "ශෙහාන් අඹේපිටිය", "යුපුන් අබේකෝන් 2022 වසරේදී ස්විට්සර්ලන්තයේදී තත්පර 9.96ක ඓතිහාසික කාලයක් වාර්තා කරමින් දකුණු ආසියාවේ වේගවත්ම මිනිසා බවට පත්විය."),
        q("ශ්‍රී ලංකාවේ මීටර් 400 ධාවන ඉසව්වේ ජාතික වාර්තාවට හිමිකම් කියන ආසියානු ක්‍රීඩා උළෙලේ රන් පදක්කම්ලාභී සුපිරි ධාවකයා කවුද?", "සුගත් තිලකරත්න (තත්පර 44.63)", "රොහාන් ප්‍රදීප් කුමාර", "කාලිංග කුමාරගේ", "අරුණ දර්ශන", "සුගත් තිලකරත්න 1998 ආසියානු ශූරතාවලියේදී තත්පර 44.63ක විස්මිත කාලයක් වාර්තා කරමින් ශ්‍රී ලංකා නාමය බැබළවීය."),
        q("ඔලිම්පික් උළෙලක කාන්තා මීටර් 100 කඩුලු පැනීමේ ඉසව්වේ අවසන් මහා තරගයට සුදුසුකම් ලැබූ එකම ශ්‍රී ලාංකික ක්‍රීඩිකාව කවුද?", "ශ්‍රියානි කුලවංශ (1996 ඇට්ලන්ටා ඔලිම්පික්)", "සුසන්තිකා ජයසිංහ", "දමයන්ති දර්ශා", "තාරිකා ප්‍රනාන්දු", "ශ්‍රියානි කුලවංශ 1996 ඇට්ලන්ටා ඔලිම්පික් උළෙලේදී මීටර් 100 කඩුලු අවසන් තරගයට තේරී පත්වී විශිෂ්ට දක්ෂතාවක් දැක්වීය."),
        q("ආසියානු ක්‍රීඩා උළෙලවලදී මීටර් 200 සහ මීටර් 400 ඉසව්වලින් රන් පදක්කම් රැසක් දිනූ ශ්‍රී ලංකාවේ සුප්‍රකට කෙටි දුර ධාවිකාව කවුද?", "දමයන්ති දර්ශා", "සුසන්තිකා ජයසිංහ", "ශ්‍රියානි කුලවංශ", "චන්ද්‍රිකා සුභාෂිණී", "දමයන්ති දර්ශා ආසියානු ක්‍රීඩා උළෙල වාර්තා තබමින් මීටර් 200 සහ 400 ඉසව්වල රන් පදක්කම් දිනාගත්තාය."),
        q("උස පැනීමේ ඉසව්වෙන් මීටර් 2.27ක උසක් පනිමින් ශ්‍රී ලංකා ජාතික වාර්තාව පිහිටවූ ආසියානු රන් පදක්කම්ලාභී ක්‍රීඩකයා කවුද?", "මංජුල කුමාර විජේසේකර", "නලින් ප්‍රියදර්ශන", "උෂාන් තිවංක", "ජනක ප්‍රසාද්", "මංජුල කුමාර ආසියානු මලල ක්‍රීඩා ශූරතාවලියේදී උස පැනීමේ රන් පදක්කම් දිනාගත් විශිෂ්ට ක්‍රීඩකයෙකි."),
        q("පිරිමි හෙල්ල විසිකිරීමේ ඉසව්වේදී පැරාලිම්පික් රන් පදක්කමක් සහ ලෝක වාර්තාවක් පිහිටවූ ශ්‍රී ලාංකික වීරෝදාර ක්‍රීඩකයා කවුද?", "දිනේෂ් ප්‍රියන්ත හේරත් (F46 කාණ්ඩය)", "ප්‍රදීප් සංජය", "සමිත් දුලාන්", "අනිල් ප්‍රසන්න", "දිනේෂ් ප්‍රියන්ත 2020 ටෝකියෝ පැරාලිම්පික් උළෙලේදී මීටර් 67.79ක ලෝක වාර්තාවක් සමගින් ශ්‍රී ලංකාවට ප්‍රථම පැරාලිම්පික් රන් පදක්කම දිනා දුන්නේය."),
        q("මලල ක්‍රීඩා ධාවන පථයේ 'මංතීරු අංක 1' (Lane 1) පිහිටා ඇත්තේ කොතැනද?", "ධාවන පථයේ ඇතුළතම දාරයේ (තණතිල්ලට මායිම්ව)", "පිටතින්ම ඇති මංතීරුවේ", "මැද මංතීරුවේ", "කැමති ඕනෑම තැනක", "මංතීරු අංකනය කෙරෙන්නේ ඇතුළත සිට පිටතට 1 සිට 8 දක්වා පිළිවෙළිනි."),
        q("මලල ක්‍රීඩාවේ කෙටි දුර ධාවකයෙකුට උපරිම වේගය රඳවාගත හැක්කේ සාමාන්‍යයෙන් මීටර් කීයක දුරක් පමණක්ද?", "මීටර් 20 සිට 30 දක්වා කෙටි දුරක් පමණි", "මීටර් 200ක් පුරා", "මීටර් 400ක් පුරා", "මීටර් 100 පුරාම එකම වේගයෙන්", "මිනිස් කායික විද්‍යාව අනුව උපරිම වේගයට පැමිණි පසු තත්පර 2-3 කට වඩා (මීටර් 20-30) එම වේගය පවත්වාගත නොහැකි අතර පසුව වේගය මඳක් පිරිහේ."),
        q("මීටර් 200 ධාවන ඉසව්වේ ආරම්භක ස්ථානය පිහිටා ඇත්තේ ධාවන පථයේ කුමන කොටසේද?", "ධාවන පථයේ පළමු වක්‍රය (Bend) ආරම්භයේ", "සෘජු මාවත මැද", "නිමාවන රේඛාව අසල", "ජල බාධකය අසල", "මීටර් 200 ධාවනය ආරම්භ වන්නේ වක්‍රයෙන් වන අතර ක්‍රීඩකයන් වක්‍රය දිගේ දිව විත් සෘජු මාවතට පිවිසේ."),
        q("වක්‍රයක් දිගේ ධාවනය කිරීමේදී කේන්ද්‍රාපසාරී බලය මඟහරවා ගැනීමට ධාවකයා කළ යුතු කායික අනුවර්තනය කුමක්ද?", "ශරීරය වක්‍රයේ ඇතුළත දෙසට (වමට) මඳක් ඇල කර ධාවනය කිරීම", "සිරුර දකුණට ඇල කිරීම", "පිටුපසට නැමීම", "කෙළින්ම ඉහළ බැලීම", "වක්‍රයේ ඇතුළට සිරුර ඇල කිරීමෙන් කේන්ද්‍රාභිසාරී බලය සමතුලිත කර වේගය ආරක්ෂා කර ගනී."),
        q("සහය දිවීමේදී යෂ්ටිය දෙන ක්‍රීඩකයා සහ ලබන ක්‍රීඩකයා අතර සිදුවන 'ශබ්ද සංඥාව' (Check mark / Verbal cue) වැදගත් වන්නේ ඇයි?", "නොබලා යෂ්ටිය ලබන්නාට නිවැරදි මොහොතේ අත පසුපසට දිගු කිරීමට සංඥා කිරීම සඳහා", "විනිසුරුවන් බිය ගැන්වීමට", "ප්‍රේක්ෂකයන්ට ඇසීමට", "දිවීම නැවැත්වීමට", "දෙන ක්‍රීඩකයා 'හෑන්ඩ්' හෝ 'හෝප්' යනුවෙන් කෑගැසූ සැනින් ලබන්නා ආපසු නොබලා තම අත පිටුපසට විහිදුවයි."),
        q("සහය දිවීමේ මීටර් 4 × 100 ඉසව්වේ සාර්ථක කණ්ඩායමක ධාවකයන් 4 දෙනා ස්ථානගත කිරීමේ උපායමාර්ගික පිළිවෙත කුමක්ද?", "1 වන සහ 3 වන ධාවකයන් වක්‍ර සඳහාද 2 වන සහ 4 වන ධාවකයන් සෘජු මාවත් සඳහාද යෙදවීම", "සියලු දෙනාම එකම වේගයෙන් දිවීම", "වේගවත්ම අය මුලට යෙදවීම පමණි", "අහඹු ලෙස යෙදවීම", "වක්‍රවල දිවීමේ විශේෂඥයන් 1 සහ 3 ටද, යෂ්ටි හුවමාරු දෙකක් කරන ඉහළ විඳදරාගැනීමක් ඇති ධාවකයා 2 ටද, විශිෂ්ට නිමාකරන්නා 4 ටද යොදවයි."),
        q("කඩුලු පැනීමේදී 'කඩුලු අතර පියවර රටාව' (Stride Pattern) පිරිමි මීටර් 110 ඉසව්වේ සාමාන්‍යයෙන් පියවර කීයක්ද?", "කඩුලු දෙකක් අතර පියවර 3ක් (3-step pattern)", "පියවර 5ක්", "පියවර 7ක්", "පියවර 2ක්", "පියවර 3ක රිද්මය පවත්වා ගැනීමෙන් සෑම කඩුල්ලක් මතින්ම එකම පෙර පාදයෙන් (Lead leg) පැනීමට හැකි වේ."),
        q("දුර පැනීමේදී ක්‍රීඩකයෙකුගේ පිම්මේ දුර තීරණය කරන තීරණාත්මකම සාධකය කුමක්ද?", "පිටත්වීමේ මොහොතේ තිරස් ප්‍රවේගය (වේගය) සහ පිටත්වීමේ කෝණය", "ක්‍රීඩකයාගේ ශරීර බර", "වැලි වලේ ප්‍රමාණය", "පිටත්වීමේ පුවරුවේ පාට", "ප්‍රවේශ ධාවනයේ උපරිම වේගය නිවැරදි පිටත්වීමේ කෝණයකට (අංශක 18-22) පරිවර්තනය කිරීම දුර තීරණය කරයි."),
        q("තුන්පිම්මේදී (Triple Jump) ක්‍රීඩකයන් තුවාල නොවී රැකගැනීමට පිටත්වීමේ පුවරුව වැලි වලේ සිට අවම වශයෙන් මීටර් කීයක් ඈතින් තැබිය යුතුද?", "පිරිමින් සඳහා මීටර් 13ක් සහ කාන්තාවන් සඳහා මීටර් 11ක්", "මීටර් 2ක් පමණි", "මීටර් 30ක්", "මීටර් 5ක්", "පාසල් මට්ටමේදී මෙය මීටර් 9ක් හෝ 11ක් විය හැකි අතර පිමි තුන අවසානයේ ආරක්ෂිතව වැලි වලට වැටිය යුතුය."),
        q("මලල ක්‍රීඩා පිටියේ විසිකිරීමේ ඉසව්වලදී (යගුලිය, කවපෙත්ත) ක්‍රීඩකයාට තම උත්සාහය සඳහා ලබාදෙන සම්මත කාලය කොපමණද?", "ක්‍රීඩකයාගේ නම කැඳවූ මොහොතේ සිට මිනිත්තු 1ක් (තත්පර 60ක්)", "තත්පර 10ක් පමණි", "මිනිත්තු 5ක්", "අසීමිත කාලයක්", "තත්පර 60 ඇතුළත විසිකිරීම සිදු නොකළහොත් එය අසාර්ථක උත්සාහයක් ලෙස සටහන් වේ."),
        q("උස පැනීමේදී ක්‍රීඩකයෙකු තරගයෙන් ඉවත් වන්නේ කවදාද?", "එක් උසකදී හෝ අනුක්‍රමික උසවල්වලදී පිට පිට තෙවරක් අසාර්ථක වූ විට හෝ ජයග්‍රහණයෙන් පසු නැවැත්වූ විට", "එක් වරක් වැටුණු වහාම", "දෙවරක් පැන්න පසු", "විනිසුරු පැවසූ විට", "අඛණ්ඩව පිමි 3ක් අසාර්ථක වන තෙක් ක්‍රීඩකයාට උස වැඩි කරමින් තරගයේ රැඳී සිටිය හැක."),
        q("උස පැනීමේදී ක්‍රීඩකයන් දෙදෙනෙකු එකම උපරිම උසක් පැන සම තත්ත්වයකට (Tie) පත්වූ විට ජයග්‍රාහකයා තීරණය කරන්නේ කෙසේද?", "අදාළ අවසාන උස අඩුම උත්සාහයන් ගණනකින් සමත් වූ ක්‍රීඩකයා ජයග්‍රහණය කිරීමෙන්", "දෙදෙනාටම කුසලාන බෙදාදීමෙන්", "වයසින් බාල ක්‍රීඩකයාට දීමෙන්", "කාසියක් වාසි බැලීමෙන්", "අවසාන උස සම නම් මුළු තරගය පුරාම අඩුම අසාර්ථක උත්සාහයන් ගණනක් ඇති ක්‍රීඩකයා ජයග්‍රහණය කරයි."),
        q("ධාවන පථයේ ධාවන ඉසව්වකදී ක්‍රීඩකයෙකු වැටුණහොත් හෝ ඇදවැටුණහොත් ඔහුට නැවත නැගිට දිවීම සම්පූර්ණ කළ හැකිද?", "ඔව්, තමන්ගේ මංතීරුවේ රැඳී සිටිමින් අන් අයට බාධා නොකර දිවීම සම්පූර්ණ කළ හැක", "නැත, වැටුණු සැනින් නුසුදුස්සෙක් වේ", "විනිසුරු අවසර දුනහොත් පමණි", "නැවත මුල සිට දිවිය යුතුය", "වැටුණද තමන්ගේ මංතීරුවේ රැඳී සිටිමින් දිවීම අවසන් කළහොත් එම කාලය සහ ස්ථානය වලංගු වේ."),
        q("මලල ක්‍රීඩා තරගාවලියකදී ක්‍රීඩකයන් උත්තේජක ඖෂධ (Doping) භාවිත කර ඇත්දැයි පරීක්ෂා කරන ජාත්‍යන්තර ආයතනය කුමක්ද?", "ලෝක උත්තේජක මර්දන ඒජන්සිය (WADA)", "ලෝක සෞඛ්‍ය සංවිධානය (WHO)", "යුනෙස්කෝ ආයතනය", "ජාත්‍යන්තර ඔලිම්පික් කමිටුව පමණි", "WADA මගින් මුත්‍ර සහ රුධිර සාම්පල පරීක්ෂා කර තහනම් උත්තේජක ගත් ක්‍රීඩකයන්ට තහනම් පනවයි."),
        q("මලල ක්‍රීඩාවේදී තහනම් උත්තේජකයක් ලෙස ඇනබොලික් ස්ටෙරොයිඩ් (Anabolic Steroids) භාවිත කිරීමෙන් ශරීරයට සිදුවන බරපතළ හානිය කුමක්ද?", "අක්මා හා වකුගඩු අකර්මණ්‍ය වීම, හෘදයාබාධ සහ ප්‍රජනක ආබාධ ඇතිවීම", "පෙනීම තියුණු වීම", "නිරෝගී බව වැඩිවීම", "අස්ථි ශක්තිමත් වීම පමණි", "ස්ටෙරොයිඩ් මගින් කෘත්‍රිමව පේශි විශාල කළද ස්වාභාවික හෝමෝන සමතුලිතතාව විනාශ වී මාරාන්තික රෝග හටගනී."),
        q("පාසල් මලල ක්‍රීඩා පුහුණුවකදී ආරම්භක ක්‍රීඩකයෙකුට මුලින්ම ප්‍රගුණ කළ යුතු අත්‍යවශ්‍යම මූලිකාංගය කුමක්ද?", "නිවැරදි ධාවන, පැනීමේ හෝ විසිකිරීමේ මූලික ශිල්පීය තාක්ෂණය (Technique)", "හැකි උපරිම බර එසවීම", "අධික වේගයෙන් දිවීම පමණි", "ජයග්‍රහණය පමණක් ඉලක්ක කිරීම", "නිවැරදි තාක්ෂණය කුඩා කලදීම හුරු කරවීමෙන් ක්‍රීඩා ආබාධ වැළකී අනාගතයේදී විශිෂ්ට දක්ෂතා දැක්විය හැක."),
        q("මලල ක්‍රීඩාවේ කෙටි දුර ධාවනයේදී 'ධාවන ඉරියව්වේ' (Running Posture) තිබිය යුතු ප්‍රධාන ලක්ෂණයක් කුමක්ද?", "හිස සහ කොඳු ඇට පෙළ කෙළින් තබා උරහිස් ලිහිල්ව ඉදිරිය බලා ධාවනය කිරීම", "හිස පහළට නමාගෙන දිවීම", "අත් දෙපසට වනමින් දිවීම", "පසුපසට ඇල වී දිවීම", "සිරුර ලිහිල්ව ඉදිරියට නැඹුරු කර දෑත් වැලමිටෙන් අංශක 90ට නවා ඉදිරියට හා පසුපසට පැද්දීම කාර්යක්ෂම ධාවනයට මඟ පාදයි."),
